// Golden vectors, determinism, resume and the stage entry point of the
// hydrology stage (spec P1-02 sections 3, 7, 8.3 and 8.4; P1-00 sections
// 5.1, 10.1 and 14 X1, X2; rule D10).
//
// The golden vectors in worldgen/tests/golden/p1-02-hydrology.txt were
// generated by worldgen/tests/reference/p1_hydrology_reference.py, the test
// writer's exact-integer reference written from the spec alone, with the
// elevation input from p1_elevation_reference.py. Each case's elevation is
// recomputed by the elevation stage and checked against the case's
// `elevation` item (equal to the elevation golden `layer` item) first, so an
// elevation change is reported as such and does not show as a hydrology
// failure. The items are then compared in step order, so a failure names
// the first step that diverges.
//
// Slow checks (the N = 512 and 1024 golden cases of 8.4, 512 thread counts,
// the hard bounds of P1-00 13.1 for hydrology) are in the test suite
// "hydrology-slow", skipped by default:
//   worldgen-tests -ts=hydrology-slow --no-skip

#include <doctest/doctest.h>

#include <algorithm>
#include <cstdint>
#include <optional>
#include <ostream>
#include <span>
#include <string>
#include <string_view>
#include <utility>
#include <vector>

#include "db_test_support.hpp"
#include "p1_02_hydrology_api.hpp"
#include "p1_02_hydrology_support.hpp"
#include "worldgen/core/hash.hpp"
#include "worldgen/data/content.hpp"
#include "worldgen/db/layer_blob.hpp"
#include "worldgen/db/reader.hpp"
#include "worldgen/generate.hpp"
#include "worldgen/inspect/geography.hpp"
